// Simple offline database using localStorage
const id = () => Date.now().toString(36) + Math.random().toString(36).slice(2);

function getTable(table) {
  try { return JSON.parse(localStorage.getItem('bwanali_' + table) || '[]'); } catch { return []; }
}
function setTable(table, rows) {
  localStorage.setItem('bwanali_' + table, JSON.stringify(rows));
  window.dispatchEvent(new CustomEvent('db-change', { detail: { table } }));
}

// Seed demo data once
if (!localStorage.getItem('bwanali_seeded')) {
  setTable('stores', [{ id: 'store-1', name: 'Demo Store', subscription_status: 'trialing', trial_started_at: new Date().toISOString(), subscription_plan: 'monthly', locked: false }]);
  setTable('staff', [{ id: 'staff-1', store_id: 'store-1', full_name: 'Admin Demo', email: 'admin@demo.com', role: 'admin', pin_code: '1234', is_active: true }]);
  setTable('products', [
    { id: 'prod-1', store_id: 'store-1', name: 'Cooking Oil 2L', barcode: '111', category: 'Groceries', unit_price: 230, cost_price: 210, stock_quantity: 20, is_active: true },
    { id: 'prod-2', store_id: 'store-1', name: 'Sugar 1kg', barcode: '222', category: 'Groceries', unit_price: 38, cost_price: 30, stock_quantity: 100, is_active: true },
    { id: 'prod-3', store_id: 'store-1', name: 'Bread Loaf', barcode: '333', category: 'Bakery', unit_price: 25, cost_price: 18, stock_quantity: 50, is_active: true },
  ]);
  setTable('company_settings', [{ id: 'settings-1', store_id: 'store-1', company_name: 'Demo Store Ltd', local_currency: 'ZMW', receipt_footer: 'Thank you!' }]);
  setTable('customers', []); setTable('sales', []); setTable('sale_items', []);
  setTable('cash_shifts', []); setTable('discount_rules', []); setTable('returns', []);
  setTable('laybys', []); setTable('store_admins', []);
  localStorage.setItem('bwanali_seeded', '1');
}

// Helper: apply filters to an array
function applyFilters(rows, filters) {
  return rows.filter(row => filters.every(f => {
    try {
      if (f.type === 'eq') return row[f.col] === f.val;
      if (f.type === 'gte') return new Date(row[f.col]) >= new Date(f.val);
      if (f.type === 'lte') return new Date(row[f.col]) <= new Date(f.val);
      if (f.type === 'not') return row[f.col] !== f.val;
      if (f.type === 'is') return row[f.col] === null || row[f.col] === undefined;
      if (f.type === 'in') return f.vals.includes(row[f.col]);
      return true;
    } catch { return false; }
  }));
}

// Simple query builder that returns thenable objects
function query(table) {
  const filters = [];
  let limitVal = null;
  let singleMode = false;
  let countMode = false;
  let headOnly = false;
  let orderCol = null;
  let orderAsc = true;

  const builder = {
    select: () => builder,
    eq: (col, val) => { filters.push({ type: 'eq', col, val }); return builder; },
    gte: (col, val) => { filters.push({ type: 'gte', col, val }); return builder; },
    lte: (col, val) => { filters.push({ type: 'lte', col, val }); return builder; },
    not: (col, val) => { filters.push({ type: 'not', col, val }); return builder; },
    is: (col, val) => { filters.push({ type: 'is', col, val }); return builder; },
    in: (col, vals) => { filters.push({ type: 'in', col, vals }); return builder; },
    order: (col, opts) => { orderCol = col; orderAsc = opts?.ascending !== false; return builder; },
    limit: (n) => { limitVal = n; return builder; },
    single: () => { singleMode = true; return builder; },
    maybeSingle: () => { singleMode = true; return builder; },
    then: (resolve) => {
      let rows = getTable(table);
      rows = applyFilters(rows, filters);
      if (orderCol) {
        rows.sort((a, b) => (a[orderCol] > b[orderCol] ? 1 : -1) * (orderAsc ? 1 : -1));
      }
      if (limitVal !== null) rows = rows.slice(0, limitVal);
      if (singleMode) return resolve({ data: rows[0] || null, error: null });
      if (countMode) {
        const total = applyFilters(getTable(table), filters).length;
        return resolve({ count: total, data: headOnly ? [] : rows, error: null });
      }
      resolve({ data: rows, error: null });
    },
    catch: () => builder,
  };

  // set count/head options (used by select with options)
  builder.select = (cols, opts) => {
    if (opts?.count === 'exact') {
      countMode = true;
      if (opts?.head) headOnly = true;
    }
    return builder;
  };

  return builder;
}

// Insert, update, delete, upsert methods (they all return thenables)
function dbInsert(table, payload) {
  const rows = getTable(table);
  const arr = Array.isArray(payload) ? payload : [payload];
  const newRows = arr.map(d => {
    const base = { id: id(), ...d };
    if (table === 'sales' && !base.invoice_number) {
      base.invoice_number = '' + (rows.length + 1);
    }
    return base;
  });
  setTable(table, [...rows, ...newRows]);
  const result = {
    data: newRows,
    error: null,
    select: () => {
      const sel = { data: newRows, error: null, then: (r) => r({ data: newRows, error: null }) };
      sel.single = () => ({ data: newRows[0] || null, error: null, then: (r) => r({ data: newRows[0] || null, error: null }) });
      return sel;
    },
    single: () => ({ data: newRows[0] || null, error: null, then: (r) => r({ data: newRows[0] || null, error: null }) }),
    then: (resolve) => resolve({ data: newRows, error: null }),
    catch: () => {},
  };
  return result;
}

function dbUpdate(table, data, filters) {
  const rows = getTable(table);
  const updated = rows.map(r => filters.every(f => r[f.col] === f.val) ? { ...r, ...data } : r);
  setTable(table, updated);
  return { error: null, then: (r) => r({ error: null }), catch: () => {} };
}

function dbDelete(table, filters) {
  const rows = getTable(table);
  const remaining = rows.filter(r => !filters.every(f => r[f.col] === f.val));
  setTable(table, remaining);
  return { error: null, then: (r) => r({ error: null }), catch: () => {} };
}

function dbUpsert(table, payload) {
  const rows = getTable(table);
  const arr = Array.isArray(payload) ? payload : [payload];
  arr.forEach(d => {
    const idx = rows.findIndex(r => r.id === d.id);
    if (idx >= 0) rows[idx] = d;
    else rows.push({ id: id(), ...d });
  });
  setTable(table, rows);
  return { error: null, then: (r) => r({ error: null }), catch: () => {} };
}

// The exported supabase object
export const supabase = {
  from: (table) => ({
    select: (cols, opts) => {
      const q = query(table);
      if (opts?.count === 'exact') {
        // We need to set count/head before building the final thenable
        // This is handled inside query builder's select.
        return q.select(cols, opts);
      }
      return q;
    },
    insert: (data) => dbInsert(table, data),
    update: (data) => ({
      eq: (col, val) => dbUpdate(table, data, [{ type: 'eq', col, val }]),
      in: (col, vals) => dbUpdate(table, data, [{ type: 'in', col, vals }]),
    }),
    delete: () => ({
      eq: (col, val) => dbDelete(table, [{ type: 'eq', col, val }]),
    }),
    upsert: (data) => dbUpsert(table, data),
  }),
  auth: {
    signInWithPassword: async ({ email, password }) => {
      const staff = getTable('staff');
      const user = staff.find(u => u.email === email && u.pin_code === password);
      if (!user) return { error: { message: 'Invalid credentials' } };
      localStorage.setItem('local_user', JSON.stringify(user));
      return { data: { user }, error: null };
    },
    signOut: async () => { localStorage.removeItem('local_user'); return { error: null }; },
    getSession: async () => {
      const user = JSON.parse(localStorage.getItem('local_user') || 'null');
      return { data: { session: user ? { user, access_token: 'offline', refresh_token: 'offline' } : null } };
    },
    onAuthStateChange: (cb) => {
      const user = JSON.parse(localStorage.getItem('local_user') || 'null');
      setTimeout(() => cb('SIGNED_IN', { user }), 10);
      return { data: { subscription: { unsubscribe: () => {} } } };
    },
    setSession: async () => ({ error: null }),
    signUp: async ({ email, password, options }) => {
      const staff = getTable('staff');
      const newUser = { id: id(), email, pin_code: password, full_name: options?.data?.full_name || 'New User', role: 'cashier', is_active: true, store_id: null };
      setTable('staff', [...staff, newUser]);
      return { data: { user: newUser }, error: null };
    },
  },
  storage: {
    from: () => ({
      upload: async () => ({ error: null }),
      getPublicUrl: () => ({ data: { publicUrl: '' } }),
    }),
  },
  rpc: () => ({ error: null, then: (r) => r({ error: null }), catch: () => {} }),
};
